#!/usr/bin/env bash
set -euo pipefail
source "$(dirname "$0")/common.sh"
allow=false; [ "${1:-}" = --allow-duplicate ] && { allow=true; shift; }
alias=${1:?usage: start-destiny.sh [--allow-duplicate] <runtime>}; runtime=$(require_runtime "$alias")
win_ps "\$root=$(ps_quote "$runtime"); \$exe=Join-Path \$root $(ps_quote "$LEGION_DESTINY_EXE_RELATIVE"); if (!(Test-Path -LiteralPath \$root -PathType Container)) { Write-Error 'RUNTIME_EXISTS=FAIL'; exit 2 }; if (!(Test-Path -LiteralPath \$exe -PathType Leaf)) { Write-Error 'DESTINY_EXECUTABLE=FAIL'; exit 3 }; \$running=@(Get-CimInstance Win32_Process -Filter \"Name='destiny2.exe'\" -ErrorAction SilentlyContinue); if (\$running.Count -gt 0 -and '$(printf '%s' "$allow")' -ne 'true') { Write-Error ('duplicate Destiny refusal; existing PIDs=' + ((\$running | ForEach-Object {\$_.ProcessId}) -join ',')); exit 4 }; \$p=Start-Process -FilePath \$exe -WorkingDirectory \$root -PassThru; Start-Sleep -Milliseconds 750; if (!(Get-Process -Id \$p.Id -ErrorAction SilentlyContinue)) { Write-Error 'PROCESS_START=FAIL'; exit 5 }; New-Item -ItemType Directory -Force -Path (Join-Path \$root '.lab-control-state') | Out-Null; @{pid=\$p.Id; runtime='$(printf '%s' "$alias")'; executable=\$exe; started_utc=[DateTime]::UtcNow.ToString('o')} | ConvertTo-Json -Compress | Set-Content -LiteralPath (Join-Path \$root '.lab-control-state\\started-destiny.json') -Encoding UTF8; Write-Output 'PROCESS_START=PASS'; Write-Output ('DESTINY_PID=' + \$p.Id); Write-Output 'LAUNCH_CONTEXT=ssh-noninteractive'; Write-Output 'INTERACTIVE_CONTROL_VERIFIED=NO'; Write-Output 'UI_STATE=unknown'; Write-Output 'GAME_TEST_STARTED=NO'"
